const clean = raw.replace(/```json|```/g, '').trim();
try {
  const parsed = JSON.parse(clean);
  return { json: parsed };
} catch(e) {
  // If parse fails, return a zero-score placeholder so the loop can continue
  return { json: { therapist_id: 'PARSE_ERROR', therapist_name: 'Unknown', compatibility_score: 0, error: e.message, raw } };
