// Reconstruct the array of therapist results from aggregated fields
// After Aggregate node, each field becomes an array
const data = $input.first().json;
const results = [];
const len = Array.isArray(data.therapist_id) ? data.therapist_id.length : 0;
for (let i = 0; i < len; i++) {
  results.push({
    therapist_id: data.therapist_id[i],
    therapist_name: data.therapist_name[i],
    compatibility_score: data.compatibility_score[i],
    matching_pillars: data.matching_pillars[i],
    rationale: data.rationale[i]
  });
}
// Sort descending by compatibility_score and return top 3
const top3 = results
  .filter(r => r.therapist_id !== 'PARSE_ERROR')
  .sort((a, b) => b.compatibility_score - a.compatibility_score)
  .slice(0, 1);
return top3.map(r => ({ json: r }));
